plan takes a dict of unique string task IDs to lists of unique prerequisite IDs, all present as keys. Return each task exactly once with every prerequisite before its dependent. Any valid order for independent tasks is allowed. An empty graph returns []. A cycle raises ValueError with message dependency cycle. Never mutate the supplied dict or its lists, including on failure. Inputs outside this domain, concurrency, large-graph performance and scheduling execution are outside the task.
def plan(dependencies):
    remaining = {name: set(parents) for name, parents in dependencies.items()}
    ready = [name for name, parents in remaining.items() if not parents]
    order = []
    while ready:
        name = ready.pop(0)
        order.append(name)
        del remaining[name]
        for child, parents in remaining.items():
            parents.discard(name)
            if not parents and child not in ready:
                ready.append(child)
    if remaining:
        raise ValueError("dependency cycle")
    return order
import unittest
from build_plan import plan

class PlanTests(unittest.TestCase):
    def test_chain(self):
        graph = {"ship": ["compile"], "compile": ["fetch"], "fetch": []}
        result = plan(graph)
        self.assertEqual(len(result), 3)
        self.assertEqual(set(result), {"fetch", "compile", "ship"})

    def test_cycle(self):
        with self.assertRaisesRegex(ValueError, "dependency cycle"):
            plan({"a": ["b"], "b": ["a"]})

    def test_independent_nodes(self):
        self.assertEqual(set(plan({"a": [], "b": []})), {"a", "b"})
        self.assertEqual(plan({}), [])
